def test_list_reporting_data_annotations_pager(transport_name: str = "grpc"):
    client = AnalyticsAdminServiceClient(
        credentials=ga_credentials.AnonymousCredentials(),
        transport=transport_name,
    )

    # Mock the actual call within the gRPC stub, and fake the request.
    with mock.patch.object(
        type(client.transport.list_reporting_data_annotations), "__call__"
    ) as call:
        # Set the response to a series of pages.
        call.side_effect = (
            analytics_admin.ListReportingDataAnnotationsResponse(
                reporting_data_annotations=[
                    resources.ReportingDataAnnotation(),
                    resources.ReportingDataAnnotation(),
                    resources.ReportingDataAnnotation(),
                ],
                next_page_token="abc",
            ),
            analytics_admin.ListReportingDataAnnotationsResponse(
                reporting_data_annotations=[],
                next_page_token="def",
            ),
            analytics_admin.ListReportingDataAnnotationsResponse(
                reporting_data_annotations=[
                    resources.ReportingDataAnnotation(),
                ],
                next_page_token="ghi",
            ),
            analytics_admin.ListReportingDataAnnotationsResponse(
                reporting_data_annotations=[
                    resources.ReportingDataAnnotation(),
                    resources.ReportingDataAnnotation(),
                ],
            ),
            RuntimeError,
        )

        expected_metadata = ()
        retry = retries.Retry()
        timeout = 5
        expected_metadata = tuple(expected_metadata) + (
            gapic_v1.routing_header.to_grpc_metadata((("parent", ""),)),
        )
        pager = client.list_reporting_data_annotations(
            request={}, retry=retry, timeout=timeout
        )

        assert pager._metadata == expected_metadata
        assert pager._retry == retry
        assert pager._timeout == timeout

        assert pager.next_page_token == "abc"
        assert str(pager).startswith(f"{pager.__class__.__name__}<")

        results = list(pager)
        assert len(results) == 6
        assert all(isinstance(i, resources.ReportingDataAnnotation) for i in results)


