def test_list_reporting_data_annotations_rest_pager(transport: str = "rest"):
    client = AnalyticsAdminServiceClient(
        credentials=ga_credentials.AnonymousCredentials(),
        transport=transport,
    )

    # Mock the http request call within the method and fake a response.
    with mock.patch.object(Session, "request") as req:
        # TODO(kbandes): remove this mock unless there's a good reason for it.
        # with mock.patch.object(path_template, 'transcode') as transcode:
        # Set the response as a series of pages
        response = (
            analytics_admin.ListReportingDataAnnotationsResponse(
                reporting_data_annotations=[
                    resources.ReportingDataAnnotation(),
                    resources.ReportingDataAnnotation(),
                    resources.ReportingDataAnnotation(),
                ],
                next_page_token="abc",
            ),
            analytics_admin.ListReportingDataAnnotationsResponse(
                reporting_data_annotations=[],
                next_page_token="def",
            ),
            analytics_admin.ListReportingDataAnnotationsResponse(
                reporting_data_annotations=[
                    resources.ReportingDataAnnotation(),
                ],
                next_page_token="ghi",
            ),
            analytics_admin.ListReportingDataAnnotationsResponse(
                reporting_data_annotations=[
                    resources.ReportingDataAnnotation(),
                    resources.ReportingDataAnnotation(),
                ],
            ),
        )
        # Two responses for two calls
        response = response + response

        # Wrap the values into proper Response objs
        response = tuple(
            analytics_admin.ListReportingDataAnnotationsResponse.to_json(x)
            for x in response
        )
        return_values = tuple(Response() for i in response)
        for return_val, response_val in zip(return_values, response):
            return_val._content = response_val.encode("UTF-8")
            return_val.status_code = 200
        req.side_effect = return_values

        sample_request = {"parent": "properties/sample1"}

        pager = client.list_reporting_data_annotations(request=sample_request)

        assert pager.next_page_token == "abc"
        assert str(pager).startswith(f"{pager.__class__.__name__}<")

        results = list(pager)
        assert len(results) == 6
        assert all(isinstance(i, resources.ReportingDataAnnotation) for i in results)

        pages = list(
            client.list_reporting_data_annotations(request=sample_request).pages
        )
        for page_, token in zip(pages, ["abc", "def", "ghi", ""]):
            assert page_.raw_page.next_page_token == token


